export const DEFAULT_INJECT = RANDOM_UUID_POLYFILL;

/**
 * 手机诊断探针（2026-09-05 临时，定位 iPhone Safari「会话列表在、对话内容空白/一直加载」）。
 * 注入到 <head> 最前、先于所有应用脚本执行；采集 onerror / unhandledrejection /
 * console.error / remote.mux WebSocket 事件 / [data-phase] 变化与转录文本长度，
 * 每 8 秒 POST /pocket-diag 上报（同源 fetch，服务端落 phone-diag.log）。
 * 探针自身全程 try/catch，任何异常不得影响页面；上报上限 40 次防刷。
 */
export const PHONE_DIAG_SCRIPT = `<script data-dsh-pocket-diag="1">!function(){try{
if(window.__dshPocketDiag)return;
var D=window.__dshPocketDiag={t0:Date.now(),id:Math.random().toString(36).slice(2),events:[],sent:0,lastScroll:-1,phases:[]};
function txt(x){try{if(x&&x.stack)return String(x.stack).slice(0,400);if(x&&x.message)return String(x.message).slice(0,400);return String(x).slice(0,400);}catch(e){return "txt-err"}}
function ev(k,d){try{D.events.push({t:Date.now()-D.t0,k:k,d:txt(d)});if(D.events.length>150)D.events.shift();}catch(e){}}
window.addEventListener("error",function(e){ev("onerror",(e.message||"")+" @"+(e.filename||"")+":"+(e.lineno||0)+" :: "+(e.error?txt(e.error):""))},true);
window.addEventListener("unhandledrejection",function(e){ev("rejection",e.reason?txt(e.reason):"no-reason")});
var oc=null;try{oc=console.error;console.error=function(){try{ev("console.error",Array.prototype.map.call(arguments,function(a){return a&&a.stack?txt(a):String(a).slice(0,200)}).join(" | ").slice(0,500))}catch(e){}return oc.apply(console,arguments)};}catch(e){}
var OW=null;try{OW=window.WebSocket;}catch(e){}
if(OW){try{
function DW(url,protos){var ws;try{ws=protos===undefined?new OW(url):new OW(url,protos);}catch(err){throw err;}
try{if(String(url).indexOf("remote.mux")!==-1){ev("ws-new",url);ws.addEventListener("open",function(){ev("ws-open","")});ws.addEventListener("close",function(c){ev("ws-close","code="+c.code+" reason="+String(c.reason).slice(0,120))});ws.addEventListener("error",function(){ev("ws-error","")});}}catch(e){}
return ws;}
DW.prototype=OW.prototype;try{DW.CONNECTING=OW.CONNECTING;DW.OPEN=OW.OPEN;DW.CLOSING=OW.CLOSING;DW.CLOSED=OW.CLOSED;}catch(e){}
window.WebSocket=DW;
}catch(e){}}
function ls(k){try{return localStorage.getItem(k)}catch(e){return "LS-ERR"}}
function poll(){try{
var ph=document.querySelector("[data-phase]");
if(ph){var p=ph.getAttribute("data-phase");if(D.phases[D.phases.length-1]!==p){D.phases.push(p);ev("phase",p);}}
var sc=document.querySelector("[data-conversation-scroll]");
if(sc){var n=(sc.innerText||"").length;if(n!==D.lastScroll){D.lastScroll=n;ev("scroll-len",String(n));}}
var boots=document.querySelectorAll("script[src]").length;if(D.bootScripts===undefined)D.bootScripts=boots;
var ml=window.__ModuleLoader__;var mls=ml?String(ml.mode):"none";if(mls!==D.mlMode){D.mlMode=mls;ev("loader-mode",mls);}
}catch(e){}}
try{setInterval(poll,2000);if(document.body)poll();else document.addEventListener("DOMContentLoaded",poll);}catch(e){}
function send(){if(D.sent>40)return;D.sent++;try{
var payload={id:D.id,t0:D.t0,now:Date.now(),ua:navigator.userAgent,sw:screen.width+"x"+screen.height,dpr:window.devicePixelRatio,
cur:ls("dsh.sessions.current"),layout:ls("dsh-pocket.layout"),phases:D.phases,lastScroll:D.lastScroll,events:D.events.slice(-80)};
fetch("/pocket-diag",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)}).catch(function(){});
}catch(e){}}
try{setInterval(send,8000);setTimeout(send,5000);setTimeout(send,15000);
document.addEventListener("visibilitychange",function(){if(document.visibilityState==="hidden")send()});
window.addEventListener("pagehide",function(){send()});}catch(e){}
}catch(e){}}();</script>`;

/** 实际注入：polyfill + 诊断探针（探针定位完成后移除）。 */
export const DEFAULT_INJECT_WITH_DIAG = DEFAULT_INJECT + PHONE_DIAG_SCRIPT;

/** 诊断日志路径：<DSH_HOME>/dsh-pocket/phone-diag.log。 */
const DIAG_LOG_PATH = (() => {
  try {
    const home = process.env.DSH_HOME || join(homedir(), '.dsh');
    return join(home, 'dsh-pocket', 'phone-diag.log');
  } catch {
    return null;
  }
})();
